#include "m5auth/vault.hpp"
#include <cassert>
#include <string>
using namespace m5auth::vault;
static std::string hx(const std::uint8_t*p,std::size_t n){static constexpr char d[]="0123456789abcdef";std::string s;for(std::size_t i=0;i<n;++i){s+=d[p[i]>>4];s+=d[p[i]&15];}return s;}template<std::size_t N>static std::array<std::uint8_t,N>seq(std::uint8_t x){std::array<std::uint8_t,N>a{};for(std::size_t i=0;i<N;++i)a[i]=x+i;return a;}
int main(){auto id=seq<kVaultIdBytes>(0);std::vector<std::uint8_t>a;assert(build_vault_aad(id,7,a));assert(hx(a.data(),a.size())=="4d35415554482d564c542d414144310000010002000102030405060708090a0b0c0d0e0f0000000000000007");VaultPlaintext v;CredentialRecord c;c.credential_id=seq<kCredentialIdBytes>(0x20);for(int i=0;i<20;++i)c.secret.push_back(0x40+i);c.issuer="synthetic-issuer-only";c.account="synthetic-account-only";c.display_name="synthetic-display-only";v.credentials.push_back(c);v.wifi=WifiRecord{"synthetic-ssid-only","synthetic-network-pass-only"};std::vector<std::uint8_t>enc;assert(encode_plaintext(v,enc));VaultPlaintext dec;assert(decode_plaintext(enc,dec)&&dec.credentials[0].secret==c.secret&&dec.wifi->password==v.wifi->password);auto key=seq<kVmkBytes>(0);auto nonce=seq<kVaultNonceBytes>(0xa0);std::string st="synthetic-vault-payload-only";std::vector<std::uint8_t>p(st.begin(),st.end());VaultEnvelope e;assert(encrypt_vault_with_nonce(p,key,id,7,nonce,e));assert(hx(e.ciphertext.data(),e.ciphertext.size())=="956112592dae76d60148f1b27216b4f300cd207cfdd62641f3604aff");assert(hx(e.tag.data(),e.tag.size())=="fe8172af15306428c847087428f8395c");std::vector<std::uint8_t>o;assert(decrypt_vault(e,key,o)&&o==p);e.tag[0]^=1;assert(!decrypt_vault(e,key,o));assert(!build_vault_aad(id,1,a,kVaultFormatVersion+1,kTargetStorageSchemaVersion));}
